          if (item.tags.length > 0) {
            console.log(`${fieldLabels.tags}     ${item.tags.join(", ")}`);
          }
          console.log("");
          console.log(item.text);
        });
      } catch (err) {
        error(errors.failures.getInboxItem, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

