import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  UlidSchema,
} from "./common.js";
import { NoteSchema } from "./task.js";

/**
 * Plan status lifecycle
 * AC: @plan-crud ac-3, ac-4
 * - draft: Initial state, editable
 * - approved: Plan reviewed and approved, ready for derivation
 * - active: Tasks have been derived from plan
 * - completed: All derived work finished
 * - rejected: Plan was rejected, terminal state
 */
export const PlanStatusSchema = z.enum([
  "draft",
  "approved",
  "active",
  "completed",
  "rejected",
]);

/**
 * Full plan schema
 * AC: @plan-crud ac-1, ac-8, ac-30
 */
export const PlanSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),

  // Content (markdown)
  content: z.string().default(""),

  // State
  status: PlanStatusSchema.default("draft"),

  // Links to derived work
  // AC: @plan-derive ac-5 - updated when tasks are derived
  derived_tasks: z.array(RefSchema).default([]),
  derived_specs: z.array(RefSchema).default([]),

  // Source tracking (if imported from file)
  // AC: @plan-import ac-24
  source_path: z.string().nullable().optional(),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  approved_at: DateTimeSchema.nullable().optional(), // AC: @plan-crud ac-3
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  // AC: @plan-crud ac-9
  notes: z.array(NoteSchema).default([]),
});

/**
 * Plan input schema (for creating new plans)
 * Most fields are optional - defaults will be applied
 */
export const PlanInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),

  // Content
  content: z.string().optional(),

  // State
  status: PlanStatusSchema.optional(),

  // Links
  derived_tasks: z.array(RefSchema).optional(),
  derived_specs: z.array(RefSchema).optional(),

  // Source tracking
  source_path: z.string().nullable().optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  approved_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes
  notes: z.array(NoteSchema).optional(),
});

/**
 * Plans file schema (collection of plans)
 * AC: @plan-crud ac-1 - stored in project.plans.yaml
 */
export const PlansFileSchema = z.object({
  kynetic_plans: z.string().default("1.0"),
  plans: z.array(PlanSchema),
});

export type PlanStatus = z.infer<typeof PlanStatusSchema>;
export type Plan = z.infer<typeof PlanSchema>;
export type PlanInput = z.infer<typeof PlanInputSchema>;
export type PlansFile = z.infer<typeof PlansFileSchema>;

import * as path from "node:path";
import chalk from "chalk";
import type { Command } from "commander";
import {
  checkSlugUniqueness,
  createNote,
  createTask,
  createTodo,
  deleteTask,
  getAuthor,
  initContext,
  type LoadedSpecItem,
  type LoadedTask,
  loadAllItems,
  loadAllTasks,
  ReferenceIndex,
  saveTask,
  scanTestCoverage,
  syncSpecImplementationStatus,
} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type { Task, TaskInput } from "../../schema/index.js";
import { alignmentCheck, errors } from "../../strings/index.js";
import {
  formatCommitGuidance,
  printCommitGuidance,
} from "../../utils/commit.js";
import { executeBatchOperation, formatBatchOutput } from "../batch.js";
import { EXIT_CODES } from "../exit-codes.js";
import {
  error,
  formatTaskDetails,
  formatTaskList,
  info,
  isJsonMode,
  output,
  success,
  warn,
} from "../output.js";
import { grepItem } from "../../utils/grep.js";

/**
 * Find a task by reference with detailed error reporting.
 * Returns the task or exits with appropriate error.
 */
function resolveTaskRef(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex,
): LoadedTask {
  const result = index.resolve(ref);

  if (!result.ok) {
    switch (result.error) {
      case "not_found":
        error(errors.reference.taskNotFound(ref));
        break;
      case "ambiguous":
        error(errors.reference.ambiguous(ref));
        for (const candidate of result.candidates) {
          const task = tasks.find((t) => t._ulid === candidate);
          const slug = task?.slugs[0] || "";
          console.error(
            `  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ""}`,
          );
        }
        break;
      case "duplicate_slug":
        error(errors.reference.slugMapsToMultiple(ref));
        for (const candidate of result.candidates) {
          console.error(`  - ${index.shortUlid(candidate)}`);
        }
        break;
    }
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Check if it's actually a task
  const task = tasks.find((t) => t._ulid === result.ulid);
  if (!task) {
    error(errors.reference.notTask(ref));
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  return task;
}

/**
 * Batch-compatible resolver that returns null instead of calling process.exit().
 * Used by executeBatchOperation to handle errors without terminating the process.
 * AC: @multi-ref-batch ac-4, ac-8 - Partial failure handling and ref resolution
 */
function resolveTaskRefForBatch(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex,
): { task: LoadedTask | null; error?: string } {
  const result = index.resolve(ref);

  if (!result.ok) {
    let errorMsg: string;
    switch (result.error) {
      case "not_found":
        errorMsg = `Reference "${ref}" not found`;
        break;
      case "ambiguous":
        errorMsg = `Reference "${ref}" is ambiguous (matches ${result.candidates.length} items)`;
        break;
      case "duplicate_slug":
        errorMsg = `Slug "${ref}" maps to multiple items`;
        break;
    }
    return { task: null, error: errorMsg };
  }

  // Check if it's actually a task
  const task = tasks.find((t) => t._ulid === result.ulid);
  if (!task) {
    return { task: null, error: `Reference "${ref}" is not a task` };
  }

  return { task };
}

/**
 * Helper function to update task fields.
 * Used by both single-ref and batch modes of task set.
 * AC: @spec-task-set-batch ac-1, ac-2, ac-4, ac-5
 */
async function setTaskFields(
  foundTask: LoadedTask,
  ctx: any,
  tasks: LoadedTask[],
  items: LoadedSpecItem[],
  _allMetaItems: any[],
  index: ReferenceIndex,
  options: any,
): Promise<{
  success: boolean;
  message?: string;
  error?: string;
  data?: unknown;
}> {
  try {
    // Check slug uniqueness if adding a new slug
    if (options.slug) {
      const slugCheck = checkSlugUniqueness(
        index,
        [options.slug],
        foundTask._ulid,
      );
      if (!slugCheck.ok) {
        return {
          success: false,
          error: `Slug "${slugCheck.slug}" already exists on ${slugCheck.existingUlid}`,
        };
      }
    }

    // Build updated task with only provided options
    const updatedTask: Task = { ...foundTask };
    const changes: string[] = [];

    if (options.title) {
      updatedTask.title = options.title;
      changes.push("title");
    }

    if (options.specRef) {
      // Validate the spec ref exists and is a spec item
      const specResult = index.resolve(options.specRef);
      if (!specResult.ok) {
        return {
          success: false,
          error: errors.reference.specRefNotFound(options.specRef),
        };
      }
      // Check it's not a task
      const isTask = tasks.some((t) => t._ulid === specResult.ulid);
      if (isTask) {
        return {
          success: false,
          error: errors.reference.specRefIsTask(options.specRef),
        };
      }
      updatedTask.spec_ref = options.specRef;
      changes.push("spec_ref");
    }

    if (options.metaRef) {
      // Validate the meta ref exists and is a meta item
      const metaRefResult = index.resolve(options.metaRef);
      if (!metaRefResult.ok) {
        return {
          success: false,
          error: errors.reference.metaRefNotFound(options.metaRef),
        };
      }

