        const refsFlag = options.refs
          ? [...new Set(options.refs as string[])]
          : undefined;

        // Batch mode or single mode?
        if (refsFlag && refsFlag.length > 0) {
          // Batch mode - AC: @spec-task-set-batch ac-1, ac-2, ac-5
          const result = await executeBatchOperation({
            positionalRef: ref,
