        // Validate arguments
        if (!ref && !options.all) {
          error(errors.usage.deriveNoRef);
          console.error("Usage:");
          console.error("  kspec derive @spec-ref");
          console.error("  kspec derive @spec-ref --flat");
          console.error("  kspec derive --all");
          process.exit(EXIT_CODES.USAGE_ERROR);
